CREATE DEFINER=`u857194726_count168`@`127.0.0.1` PROCEDURE `add_currency_to_account` (IN `p_account_id` INT, IN `p_currency_id` INT, IN `p_is_default` TINYINT(1))   BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    
    START TRANSACTION;
    
    -- 检查账户是否存在
    IF NOT EXISTS (SELECT 1 FROM account WHERE id = p_account_id) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = '账户不存在';
    END IF;
    
    -- 检查货币是否存在
    IF NOT EXISTS (SELECT 1 FROM currency WHERE id = p_currency_id) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = '货币不存在';
    END IF;
    
    -- 检查是否已经存在该关联
    IF EXISTS (SELECT 1 FROM account_currency WHERE account_id = p_account_id AND currency_id = p_currency_id) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = '该账户已经关联了此货币';
    END IF;
    
    -- 如果设置为默认货币，取消其他默认货币
    IF p_is_default = 1 THEN
        UPDATE account_currency 
        SET is_default = 0 
        WHERE account_id = p_account_id;
    END IF;
    
    -- 插入新关联
    VALUES (p_account_id, p_currency_id, p_is_default);
    
    COMMIT;
END$$

CREATE DEFINER=`u857194726_count168`@`127.0.0.1` PROCEDURE `remove_currency_from_account` (IN `p_account_id` INT, IN `p_currency_id` INT)   BEGIN
    -- 所有变量声明必须在BEGIN块的最开始
    DECLARE remaining_count INT;
    DECLARE is_default_currency TINYINT(1);
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    
    START TRANSACTION;
    
    -- 检查该账户是否还有其他货币
    SELECT COUNT(*) INTO remaining_count
    FROM account_currency
    WHERE account_id = p_account_id;
    
    IF remaining_count <= 1 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = '账户必须至少保留一个货币，无法删除';
    END IF;
    
    -- 检查要删除的货币是否为默认货币
    SELECT is_default INTO is_default_currency
    FROM account_currency
    WHERE account_id = p_account_id AND currency_id = p_currency_id;
    
    -- 删除关联
    DELETE FROM account_currency
    WHERE account_id = p_account_id AND currency_id = p_currency_id;
    
    -- 如果删除的是默认货币，将第一个货币设为默认
    IF is_default_currency = 1 THEN
        UPDATE account_currency
        SET is_default = 1
        WHERE account_id = p_account_id
        ORDER BY created_at ASC
        LIMIT 1;
    END IF;
    
    COMMIT;
END$$

CREATE DEFINER=`u857194726_count168`@`127.0.0.1` PROCEDURE `set_default_currency_for_account` (IN `p_account_id` INT, IN `p_currency_id` INT)   BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    
    START TRANSACTION;
    
    -- 检查关联是否存在
    IF NOT EXISTS (SELECT 1 FROM account_currency WHERE account_id = p_account_id AND currency_id = p_currency_id) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = '账户未关联此货币';
    END IF;
    
    -- 取消所有默认货币
    UPDATE account_currency 
    SET is_default = 0 
    WHERE account_id = p_account_id;
    
    -- 设置新的默认货币
    UPDATE account_currency 
    SET is_default = 1 
    WHERE account_id = p_account_id AND currency_id = p_currency_id;
    
    COMMIT;
END$$

CREATE DEFINER=`u857194726_count168`@`127.0.0.1` PROCEDURE `sp_cleanup_backup_data` ()   BEGIN
  -- 删除 data_captures_backup 中7天前的数据
  DELETE FROM `data_captures_backup` 
  WHERE `backup_created_at` < DATE_SUB(NOW(), INTERVAL 7 DAY);
  
  -- 删除 data_capture_details_backup 中7天前的数据
  DELETE FROM `data_capture_details_backup` 
  WHERE `backup_created_at` < DATE_SUB(NOW(), INTERVAL 7 DAY);
  
  -- 删除 data_capture_templates_backup 中7天前的数据
  DELETE FROM `data_capture_templates_backup` 
