  -- 删除 transactions_backup 中7天前的数据
  DELETE FROM `transactions_backup` 
  WHERE `backup_created_at` < DATE_SUB(NOW(), INTERVAL 7 DAY);
  
  -- 删除 transactions_rate_backup 中7天前的数据
