END$$

CREATE DEFINER=`u857194726_count168`@`127.0.0.1` PROCEDURE `sp_update_account_balance` (IN `p_capture_id` INT, IN `p_account_id` VARCHAR(50), IN `p_currency_id` VARCHAR(10))   BEGIN
    DECLARE v_processed_amount DECIMAL(15,2);
    DECLARE v_previous_balance DECIMAL(15,2);
    DECLARE v_bf DECIMAL(15,2);
    DECLARE v_total_win_loss DECIMAL(15,2);
    DECLARE v_total_cr_dr DECIMAL(15,2);
    DECLARE v_balance DECIMAL(15,2);
    DECLARE v_prev_capture_id INT;
    DECLARE v_capture_date DATE;
    
    -- 获取当前 capture 的日期
    SELECT capture_date INTO v_capture_date
    FROM data_captures
    WHERE id = p_capture_id;
    
    -- 获取本期的 processed_amount（如果 data_capture_details 表存在且有数据）
    -- 如果表不存在或没有数据，则为 0
    SET v_processed_amount = 0;
    
    -- 尝试从 data_capture_details 获取
    BEGIN
        DECLARE CONTINUE HANDLER FOR SQLSTATE '42S02' SET v_processed_amount = 0;
        
        SELECT COALESCE(SUM(dcd.processed_amount), 0) INTO v_processed_amount
        FROM data_capture_details dcd
        JOIN account a ON a.id = dcd.account_id
        WHERE dcd.capture_id = p_capture_id 
            AND a.account_id = p_account_id
            AND dcd.currency_id = (SELECT id FROM currency WHERE code = p_currency_id LIMIT 1);
    END;
    
    -- 获取上期的 capture_id
    SELECT id INTO v_prev_capture_id
    FROM data_captures
    WHERE capture_date < v_capture_date
    ORDER BY capture_date DESC
    LIMIT 1;
    
    -- 获取上期的 balance
    IF v_prev_capture_id IS NOT NULL THEN
        SELECT COALESCE(balance, 0) INTO v_previous_balance
        FROM account_balance_summary
        WHERE capture_id = v_prev_capture_id
            AND account_id = p_account_id
            AND currency_id = p_currency_id;
    ELSE
        SET v_previous_balance = 0;
    END IF;
    
    -- 如果上期没有数据，设为0
    IF v_previous_balance IS NULL THEN
        SET v_previous_balance = 0;
    END IF;
    
    -- 计算 B/F
    SET v_bf = v_previous_balance + v_processed_amount;
    
    -- 汇总本期的 Win/Loss
    SELECT COALESCE(SUM(win_loss), 0) INTO v_total_win_loss
    FROM payment
    WHERE capture_id = p_capture_id
        AND account_id = p_account_id
        AND currency_id = p_currency_id;
    
    -- 汇总本期的 Cr/Dr
    SELECT COALESCE(SUM(cr_dr), 0) INTO v_total_cr_dr
    FROM payment
    WHERE capture_id = p_capture_id
        AND account_id = p_account_id
        AND currency_id = p_currency_id;
    
    -- 计算最终 balance
    SET v_balance = v_bf + v_total_win_loss + v_total_cr_dr;
    
    -- 先检查记录是否存在
    SET @existing_id = NULL;
    SELECT id INTO @existing_id
    FROM account_balance_summary
    WHERE capture_id = p_capture_id
        AND account_id = p_account_id
        AND currency_id = p_currency_id
    LIMIT 1;
    
    -- 如果存在则更新，否则插入
    IF @existing_id IS NOT NULL THEN
        UPDATE account_balance_summary
        SET processed_amount = v_processed_amount,
            previous_balance = v_previous_balance,
            bf = v_bf,
            total_win_loss = v_total_win_loss,
            total_cr_dr = v_total_cr_dr,
            balance = v_balance,
            last_updated = CURRENT_TIMESTAMP
        WHERE id = @existing_id;
    ELSE
            capture_id, account_id, currency_id, 
            processed_amount, previous_balance, bf,
            total_win_loss, total_cr_dr, balance
        ) VALUES (
            p_capture_id, p_account_id, p_currency_id,
            v_processed_amount, v_previous_balance, v_bf,
            v_total_win_loss, v_total_cr_dr, v_balance
        );
    END IF;
END$$

DELIMITER ;

