CREATE TRIGGER `trg_cleanup_submitted_processes` AFTER DELETE ON `data_captures` FOR EACH ROW BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM data_captures
    WHERE process_id = OLD.process_id
      AND ( (created_by IS NULL AND OLD.created_by IS NULL)
            OR created_by = OLD.created_by )
      AND user_type = OLD.user_type
      AND capture_date = OLD.capture_date
  ) THEN
    DELETE FROM submitted_processes
    WHERE process_id = OLD.process_id
      AND user_type = OLD.user_type
      AND date_submitted = OLD.capture_date
      AND user_id = IFNULL(OLD.created_by, user_id); -- 可视需要调整
  END IF;
END
$$
DELIMITER ;
